INSERT OR REPLACE INTO chapters (id, projectId, title, subtitle, content, "order", status, lastEditedBy, updatedAt) VALUES ('chap_proj_56_4', 'proj_56', 'Bab 4: Konflik Dan Ketegangan Lapangan — Kumpulan Esai Kebudayaan Kontemporer', 'Titik Balik Penyelidikan', '[[ KUMPULAN ESAI KEBUDAYAAN KONTEMPORER — BAB 4 ]]' || char(10) || '' || char(10) || 'Siang hari di pertengahan musim hujan. Hujan deras tiba-tiba mengguyur lereng bukit, mengubah jalan tanah menjadi lumpur lengket yang menyulitkan langkah kami. Sepeda motor kami terpaksa ditinggalkan di pinggir warung warga.' || char(10) || '' || char(10) || 'Saat kami mendekati lokasi sumur tua di belakang bangunan kosong, kami menyadari ada jejak kaki segar di atas tanah berlumpur. Seseorang telah mendahului kami!' || char(10) || '' || char(10) || '"Hati-hati," bisik Broto sambil memegang kayu jati lapuk di tangannya. ' || char(10) || '' || char(10) || 'Penutup kayu sumur tua itu sudah bergeser. Tali tambang tebal tergantung menjuntai ke dalam lubang sumur yang gelap dan berbau lembap. Dari dalam kedalaman sumur, terdengar gesekan besi yang samar.' || char(10) || '' || char(10) || '"Siapa di dalam?" teriakku dengan suara lantang yang memecah kesunyian hujan.' || char(10) || '' || char(10) || 'Seketika itu juga, sesosok bayangan meloncat keluar dari balik reruntuhan tembok samping. Tanpa sepatah kata pun, orang berjaket hitam itu berlari cepat menembus semak-semak bambu, meninggalkan sebuah tas kulit tua yang terjatuh di pinggir sumur.', 4, 'final', 'Siti Rahmania', '2026-09-05T04:00:00.000Z');
INSERT OR REPLACE INTO chapters (id, projectId, title, subtitle, content, "order", status, lastEditedBy, updatedAt) VALUES ('chap_proj_56_5', 'proj_56', 'Bab 5: Puncak Penemuan Berkas — Kumpulan Esai Kebudayaan Kontemporer', 'Membuka Brankas Terlarang', '[[ KUMPULAN ESAI KEBUDAYAAN KONTEMPORER — BAB 5 ]]' || char(10) || '' || char(10) || 'Tas kulit tua yang tertinggal itu basah oleh air hujan. Dengan tangan gemetar, kami membuka ritsleting besinya yang sudah berkarat. Di dalamnya terdapat sebuah kotak logam berukuran sedang dengan gembok kuningan tebal.' || char(10) || '' || char(10) || 'Kami membawa kotak itu kembali ke ruang kerja di studio. Lampu meja dinyalakan terang. Dengan bantuan perkakas kecil dan sedikit minyak pelumas, gembok tua itu akhirnya berbunyi ''klik'' dan terbuka.' || char(10) || '' || char(10) || 'Isi kotak itu membuat kami terpana.' || char(10) || '' || char(10) || 'Bukan perhiasan atau uang tua, melainkan puluhan lembar foto hitam-putih berukuran besar, buku catatan harian bertinta biru bertuliskan tangan rapi, serta Peta Rahasia Jalur Kereta Api Kompartemen Zaman Kolonial yang belum pernah dipublikasikan di arsip nasional manapun.' || char(10) || '' || char(10) || '"Lihat foto ini," bisik Siti. "Ini adalah foto pertemuan para tokoh pergerakan nasional di Jogja pada tahun 1928. Wajah-wajah di foto ini... sebagian besar belum pernah masuk dalam buku sejarah sekolah!"', 5, 'final', 'Siti Rahmania', '2026-09-05T05:00:00.000Z');
INSERT OR REPLACE INTO chapters (id, projectId, title, subtitle, content, "order", status, lastEditedBy, updatedAt) VALUES ('chap_proj_56_6', 'proj_56', 'Bab 6: Pembuktian Dan Analisis Komparatif — Kumpulan Esai Kebudayaan Kontemporer', 'Menyusun Kembali Cerita', '[[ KUMPULAN ESAI KEBUDAYAAN KONTEMPORER — BAB 6 ]]' || char(10) || '' || char(10) || 'Hari-hari berikutnya dihabiskan di depan layar monitor dan tumpukan buku referensi. Kami membandingkan tulisan tangan di buku harian dengan arsip otentik milik Perpustakaan Nasional dan Arsip Daerah.' || char(10) || '' || char(10) || 'Metode pengujian tingkat keasaman kertas (pH test) dan analisis gaya bahasa mengonfirmasi bahwa naskah ini memang ditulis secara berkala antara tahun 1928 hingga 1935 oleh seorang juru ketik keraton yang juga menjadi anggota rahasia pergerakan.' || char(10) || '' || char(10) || '"Setiap paragraf di sini memiliki ritme narasi yang jujur," catatku dalam log revisi studio. "Penulisnya tidak berusaha mendramatisir keadaan. Dia mencatat harga beras, harga tiket kereta, kecemasan warga saat patroli malam, hingga obrolan hangat di warung kopi."' || char(10) || '' || char(10) || 'Inilah kekuatan dari penulisan berbasis fakta dan pengalaman nyata manusia. Tulisan seperti ini memiliki ''jiwa'' yang tidak akan pernah bisa ditiru oleh mesin atau algoritma generatif buatan.', 6, 'final', 'Siti Rahmania', '2026-09-05T06:00:00.000Z');
INSERT OR REPLACE INTO chapters (id, projectId, title, subtitle, content, "order", status, lastEditedBy, updatedAt) VALUES ('chap_proj_56_7', 'proj_56', 'Bab 7: Refleksi Dan Rekonstruksi Naskah — Kumpulan Esai Kebudayaan Kontemporer', 'Menuju Draf Final', '[[ KUMPULAN ESAI KEBUDAYAAN KONTEMPORER — BAB 7 ]]' || char(10) || '' || char(10) || 'Proses kolaborasi penulisan naskah ini telah memasuki tahap penyuntingan akhir. Draf bab demi bab kami kaji bersama di ruang kerja Studio Buku. Setiap anggota tim memberikan catatan kritis pada papan bab.' || char(10) || '' || char(10) || '"Bagian deskripsi latar di Bab 4 perlu kita pertebal," saran Siti. "Pembaca harus bisa merasakan dinginnya angin lereng bukit dan bau tanah basah saat hujan menyiram lereng."' || char(10) || '' || char(10) || '"Setuju," sahut Broto. "Dan di Bab 5, kutipan dari buku catatan harian harus kita tampilkan dalam format khusus agar otentisitase naskah aslinya tetap terjaga."' || char(10) || '' || char(10) || 'Proses ''nulis bareng'' ini membuktikan bahwa dua atau tiga kepala yang berpikir bersama mampu melahirkan karya yang jauh lebih kaya, berkedalaman, dan bernyawa dibandingkan penulisan tunggal yang terisolasi.', 7, 'review', 'Siti Rahmania', '2026-09-05T07:00:00.000Z');
INSERT OR REPLACE INTO chapters (id, projectId, title, subtitle, content, "order", status, lastEditedBy, updatedAt) VALUES ('chap_proj_56_8', 'proj_56', 'Bab 8: Epilog Dan Harapan Baru — Kumpulan Esai Kebudayaan Kontemporer', 'Warisan Untuk Masa Depan', '[[ KUMPULAN ESAI KEBUDAYAAN KONTEMPORER — BAB 8 ]]' || char(10) || '' || char(10) || 'Naskah buku ini akhirnya siap dipersembahkan kepada publik. Dari sebuah dokumen kusam berstempel merah pudar di lemari tua, kini telah menjelma menjadi sebuah karya buku utuh yang siap dibaca oleh ribuan generasi mendatang.' || char(10) || '' || char(10) || 'Sejarah dan karya literasi bukan sekadar deretan angka tahun atau nama tokoh yang harus dihafalkan. Literatur adalah jembatan emosional yang menghubungkan rasa kemanusiaan kita dengan orang-orang yang pernah hidup, berjuang, dan bermimpi di atas tanah yang sama puluhan tahun lalu.' || char(10) || '' || char(10) || 'Terima kasih kepada seluruh tim co-author, peneliti lapangan, dan pembaca setia di Studio Buku yang telah mengawal perjalanan naskah ini dari draf awal hingga terbit.' || char(10) || '' || char(10) || 'Semoga naskah ini menjadi penyala api literasi dan inspirasi bagi lahirnya buku-buku kolaboratif berikutnya di Indonesia.', 8, 'review', 'Siti Rahmania', '2026-09-05T08:00:00.000Z');
INSERT OR REPLACE INTO chapters (id, projectId, title, subtitle, content, "order", status, lastEditedBy, updatedAt) VALUES ('chap_proj_57_1', 'proj_57', 'Bab 1: Awal Mula Dan Suasana Pagi — Kisah Pengrajin Keramik Plered', 'Langkah Pertama Di Pintu Masuk', '[[ KISAH PENGRAJIN KERAMIK PLERED — BAB 1 ]]' || char(10) || '' || char(10) || 'Pagi itu, kabut tipis masih menggantung rendah di atas pepohonan tua. Suara dentang lonceng gereja tua di kejauhan terdengar samar, berpadu dengan deru mesin sepeda motor tua yang melintas pelan di jalan berbatu.' || char(10) || '' || char(10) || 'Saya menatap lembaran kertas kusam di atas meja kayu. Aromanya khas—perpaduan antara kertas lapuk, tinta cina tua, dan sedikit aroma kelembapan tanah yang tersisa dari hujan semalam. Di sinilah semuanya bermula. Sebuah perjalanan panjang yang tidak pernah saya bayangkan sebelumnya.' || char(10) || '' || char(10) || '"Apakah kamu yakin berkas ini asli?" tanya Broto sambil mengembuskan asap rokok kreteknya. Matanya yang sembab menatap tajam ke arah stempel merah pudar di sudut kanan bawah dokumen.' || char(10) || '' || char(10) || '"Stempel ini menggunakan tinta pigmen merah raksasa zaman kolonial," jawabku pelan. "Hanya ada tiga instansi di Jawa Tengah yang menggunakan stempel unik ini pada tahun 1930-an. Kita tidak sedang memegang dokumen biasa, Broto."' || char(10) || '' || char(10) || 'Dia terdiam sejenak. Tangannya yang kasar menyentuh pinggiran kertas dengan sangat hati-hati, seolah takut lembaran sejarah itu akan hancur menjadi debu jika tersentuh terlalu keras.', 1, 'final', 'Kirana Maharani', '2026-09-04T01:00:00.000Z');
INSERT OR REPLACE INTO chapters (id, projectId, title, subtitle, content, "order", status, lastEditedBy, updatedAt) VALUES ('chap_proj_57_2', 'proj_57', 'Bab 2: Jejak Pertama Dan Pengamatan — Kisah Pengrajin Keramik Plered', 'Menelusuri Bukti Yang Tersisa', '[[ KISAH PENGRAJIN KERAMIK PLERED — BAB 2 ]]' || char(10) || '' || char(10) || 'Menelusuri jejak masa lalu membutuhkan kesabaran yang luar biasa. Kami melangkah menyusuri lorong sempit di belakang kompleks bangunan tua Kotabaru. Dinding-dinding bata tebal berwarna putih kusam tampak terkelupas di beberapa bagian, memperlihatkan susunan bata merah tua buatan pabrik lokal zaman kolonial.' || char(10) || '' || char(10) || 'Di sudut lorong, seorang lelaki tua sedang merapikan lembaran koran bekas. Ia mengamati kedatangan kami dengan pandangan curiga. Di kota seperti ini, kehadiran dua orang asing yang membawa buku catatan tebal dan kamera tua selalu memancing pertanyaan.' || char(10) || '' || char(10) || '"Pak, apakah Bapak ingat siapa yang dulu tinggal di rumah sudut itu sebelum tahun 1970?" tanyaku dengan nada sehalus mungkin, sambil menyodorkan sebotol minuman hangat.' || char(10) || '' || char(10) || 'Lelaki tua itu membetulkan letak kacamata tebalnya. "Rumah itu dulu milik Meneer Van Der Berg. Tapi setelah peristiwa pertengahan dekade enam puluhan, rumah itu dikosongkan. Banyak dokumen yang dibakar di halaman belakang, tapi konon ada satu peti yang dimasukkan ke dalam sumur tua."' || char(10) || '' || char(10) || 'Pernyataan itu membuat jantungku berdegup lebih kencang. Peti di sumur tua!', 2, 'final', 'Kirana Maharani', '2026-09-04T02:00:00.000Z');
INSERT OR REPLACE INTO chapters (id, projectId, title, subtitle, content, "order", status, lastEditedBy, updatedAt) VALUES ('chap_proj_57_3', 'proj_57', 'Bab 3: Dialektika Dan Rahasia Tersembunyi — Kisah Pengrajin Keramik Plered', 'Membuka Lembaran Baru', '[[ KISAH PENGRAJIN KERAMIK PLERED — BAB 3 ]]' || char(10) || '' || char(10) || 'Diskusi malam itu berlangsung hangat di kedai kopi kecil tak jauh dari stasiun. Di bawah pendar lampu kuning remang-remang, kami membentangkan peta topografi wilayah Progo tahun 1928.' || char(10) || '' || char(10) || '"Jika kita melihat garis kontur ini," kataku sambil menunjuk garis meliuk warna cokelat tua, "aliran sungai zaman dulu berbelok tepat di sebelah barat bukit. Artinya, lokasi candi yang hilang tidak mungkin berada di lembah utara."' || char(10) || '' || char(10) || 'Siti, kawan peneliti kami dari bidang arkeologi, mengangguk setuju. "Data epigrafi yang saya baca dari prasasti batu hitam mendukung analisis itu. Ada sebutan ''Watang Anum'' yang merujuk pada pemukiman di tepi barat sungai, bukan di lembah."' || char(10) || '' || char(10) || 'Saling silang argumen akademis ini menjadi bahan bakar utama proyek penulisan kami. Setiap fakta tidak langsung diterima begitu saja. Harus ada verifikasi lapangan, pembandingan dokumen silang, dan wawancara dengan sesepuh desa setempat.' || char(10) || '' || char(10) || '"Menulis naskah seperti ini," ujar Siti sambil menyeruput kopi gayo hangatnya, "bukan sekadar merangkai kata indah, melainkan menyusun kembali puzzle kehidupan manusia yang sempat terputus oleh waktu."', 3, 'final', 'Kirana Maharani', '2026-09-04T03:00:00.000Z');
INSERT OR REPLACE INTO chapters (id, projectId, title, subtitle, content, "order", status, lastEditedBy, updatedAt) VALUES ('chap_proj_57_4', 'proj_57', 'Bab 4: Konflik Dan Ketegangan Lapangan — Kisah Pengrajin Keramik Plered', 'Titik Balik Penyelidikan', '[[ KISAH PENGRAJIN KERAMIK PLERED — BAB 4 ]]' || char(10) || '' || char(10) || 'Siang hari di pertengahan musim hujan. Hujan deras tiba-tiba mengguyur lereng bukit, mengubah jalan tanah menjadi lumpur lengket yang menyulitkan langkah kami. Sepeda motor kami terpaksa ditinggalkan di pinggir warung warga.' || char(10) || '' || char(10) || 'Saat kami mendekati lokasi sumur tua di belakang bangunan kosong, kami menyadari ada jejak kaki segar di atas tanah berlumpur. Seseorang telah mendahului kami!' || char(10) || '' || char(10) || '"Hati-hati," bisik Broto sambil memegang kayu jati lapuk di tangannya. ' || char(10) || '' || char(10) || 'Penutup kayu sumur tua itu sudah bergeser. Tali tambang tebal tergantung menjuntai ke dalam lubang sumur yang gelap dan berbau lembap. Dari dalam kedalaman sumur, terdengar gesekan besi yang samar.' || char(10) || '' || char(10) || '"Siapa di dalam?" teriakku dengan suara lantang yang memecah kesunyian hujan.' || char(10) || '' || char(10) || 'Seketika itu juga, sesosok bayangan meloncat keluar dari balik reruntuhan tembok samping. Tanpa sepatah kata pun, orang berjaket hitam itu berlari cepat menembus semak-semak bambu, meninggalkan sebuah tas kulit tua yang terjatuh di pinggir sumur.', 4, 'final', 'Kirana Maharani', '2026-09-04T04:00:00.000Z');
